import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.27 released — Mutation testing sweep (Stryker rollout + 4-tier threshold SSOT + 12-axis release gate + 33-package coverage)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.27/gh-discussions-announcement.md","filePath":"announcements/v1.27/gh-discussions-announcement.md"}'),r={name:"announcements/v1.27/gh-discussions-announcement.md"};function i(n,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="kiwa-v1-27-released-—-mutation-testing-sweep-stryker-rollout-4-tier-threshold-ssot-12-axis-release-gate-33-package-coverage" tabindex="-1">kiwa v1.27 released — Mutation testing sweep (Stryker rollout + 4-tier threshold SSOT + 12-axis release gate + 33-package coverage) <a class="header-anchor" href="#kiwa-v1-27-released-—-mutation-testing-sweep-stryker-rollout-4-tier-threshold-ssot-12-axis-release-gate-33-package-coverage" aria-label="Permalink to &quot;kiwa v1.27 released — Mutation testing sweep (Stryker rollout + 4-tier threshold SSOT + 12-axis release gate + 33-package coverage)&quot;">​</a></h1><p>v1.27 is out. After v1.11 landed <code>@kiwa-test/quality-metrics</code> v0.1 with <code>mutationFromCounts</code> and a fixed 60 % kill-rate axis on the 11-axis release gate, v1.27 stacks a <strong>4-tier mutation threshold SSOT + Stryker infrastructure across all 33 kiwa packages + a 12-axis release gate with <code>mutation.tier</code> as the new axis</strong>. Every axis is a <code>packages/quality-metrics/src/gate.ts</code> pure primitive (no adapter, no network) so tests / fixtures / release gates run deterministically. <code>@kiwa-test/quality-metrics</code> v0.2.0 → v0.3.0 minor bump reflects the tier-aware surface addition — the v0.2 API surface (<code>assembleReport</code> / <code>evaluateReleaseGate</code> / <code>mutationFromCounts</code> / <code>emitMarkdown</code>) stays completely intact.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/quality-metrics</code> v0.3.0</strong> (4-tier mutation threshold SSOT + tier-aware 12-axis release gate minor bump). v0.2&#39;s <code>assembleReport</code> + <code>evaluateReleaseGate</code> + <code>mutationFromCounts</code> + <code>emitMarkdown</code> + every <code>*Metric</code> type alias keeps every prior signature. v0.3 layers 5 primitives on top: <code>DEFAULT_MUTATION_TIER_THRESHOLDS</code> (the 4-tier floor table) + <code>resolveMutationTier</code> + <code>assertMutationTier</code> + <code>MutationTier</code> type + <code>ReleaseGateContext</code> type. Existing 7 / 11 axis paths stay unchanged when <code>mutationTier</code> is omitted from <code>evaluateReleaseGate</code> — no v0.2 caller is asked to migrate.</li><li><strong>v1.27-1 Stryker infra 基盤</strong> (Issue #957). 34-package <code>stryker.config.mjs</code> land + <code>test:mutation</code> script + <code>.stryker-tmp/</code> gitignore + <code>.mutation-baseline/{package}.json</code> persistence + 4-tier threshold rationale SSOT (<code>docs/quality/mutation-thresholds.md</code>) — Core 80 % / Framework 70 % / SaaS 65 % / Test type 60 %, each tier justified against the shape of code Stryker runs over rather than package name. Baseline JSON schema is a single 5-field object (<code>package</code> / <code>tier</code> / <code>killRate</code> / <code>survivedIds</code> / <code>runAt</code>) — no bespoke shape per package.</li><li><strong>v1.27-2 core + framework layer mutation sweep</strong> (Issue #963). 9 core-layer packages (core / dapp / api / ui / data / cli-test / observability / e2e / cli) + 11 framework-adapter packages (a11y / visual / nextjs / nuxt / sveltekit / remix / astro / solidstart / qwikcity / edge / fresh / hono / solidjs). 3-layer harness (source + test + mutant) SSOT + parallel Stryker run across 20 packages with tier-aware gates.</li><li><strong>v1.27-3 test type + SaaS layer mutation sweep</strong> (Issue #966). 3 test-type packages (a11y / visual / component) + 10 SaaS-layer packages (auth / queue / cache / orm / payment / streaming / search / mcp / agent / realtime). Provider-specific baseline patterns kept in the same <code>.mutation-baseline/{package}.json</code> shape so <code>PACKAGE_TIER</code> map stays single-file.</li><li><strong>v1.27-4 release gate 12-axis 拡張</strong> (Issue #959). <code>evaluateReleaseGate(report, thresholdOverrides, { mutationTier })</code> opts a report into a 12th axis (<code>mutation.tier</code>) that fails when kill-rate drops below the tier floor. <code>resolveMutationTier</code> picks the tier from a <code>PACKAGE_TIER</code> map, <code>assertMutationTier</code> asserts the tier floor and throws a <code>MutationTierBelowFloor</code> error with the offending numbers when it fails.</li><li><strong>v1.27-5 docs 補強</strong> (Issue #968). tutorial 50 (Stryker + kill-rate baseline + tier gate walkthrough) + tutorial 51 (22 → 33 package sweep methodology) + concept doc <code>mutation-testing-ssot.md</code> (kill rate + 4-tier threshold + baseline persistence + 12-axis release gate SSOT) + migration guide <code>v1.26-to-v1.27.md</code> (additive-only, breaking change 0) + snippet validation <code>packages/quality-metrics/tests/docs-tutorial-v1.27.test.ts</code> (20 test) re-runs every tutorial code snippet against the real <code>@kiwa-test/quality-metrics</code> v0.3 API so drift is structurally blocked.</li><li><strong>v1.27-6 publish</strong> (Issue #961, this PR). plugin.json 1.26.0 → 1.27.0 + description v1.26 → v1.27 marker + new mutation-focused keywords + Roadmap ✅ v1.27 row + announcement 4 file + release-smoke <code>v1-27-publish.test.ts</code> (7 axis publish artefact invariant) + docs-e2e <code>V1_27_PAGES</code> (5 page render check) + <strong>release script filter fix</strong> — <code>@kiwa-test/quality-metrics</code> added to both build (<code>-F</code>) and publish (<code>--filter</code>) halves (v1.14 payment omission + v1.25 perf-harness lesson, 3rd application of the same pattern).</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#957 / #963 / #966 / #959 / #968 / #961)</li><li><strong>6 PRs merged</strong> (v1.27-1 through v1.27-6)</li><li><strong>1 npm minor bump</strong> (<code>@kiwa-test/quality-metrics</code> v0.2.0 → v0.3.0) — kiwa runtime fixture count stays 34</li><li><strong>33 packages</strong> with Stryker rollout (22 already had a config from earlier milestones, 11 new in v1.27-1 through v1.27-3)</li><li><strong>4 tiers</strong> (Core 80 % / Framework 70 % / SaaS 65 % / Test type 60 %) in the mutation threshold SSOT</li><li><strong>12 axes</strong> on the release gate (coverage + test count + fidelity + perf p95 + AI-LLM cost / latency / token / accuracy + mutation kill + mutation tier + 2 legacy = 12, tier axis is the new one)</li><li><strong>20 snippet-validation tests</strong> in <code>packages/quality-metrics/tests/docs-tutorial-v1.27.test.ts</code></li></ul><h2 id="why-4-tiers-and-not-one-universal-floor" tabindex="-1">Why 4 tiers (and not one universal floor) <a class="header-anchor" href="#why-4-tiers-and-not-one-universal-floor" aria-label="Permalink to &quot;Why 4 tiers (and not one universal floor)&quot;">​</a></h2><p>Mutation tests without a shared tier system fail three ways.</p><ul><li><strong>Threshold drift</strong>. One package uses 90 / 80 / 80 as the gate, another uses 80 / 60 / 50, a third uses 65 / 55 / 50. When a mutation regression fires on package A but not on B, the reader cannot tell whether B is genuinely fine or whether B&#39;s gate is looser than A&#39;s. The 4-tier SSOT names the <strong>shape</strong> of the code Stryker runs over — Core (pure primitives that everything imports) / Framework (adapter shells that translate to a framework) / SaaS (provider mocks that need to swap in for real APIs) / Test type (test-runner helpers). Every downstream config picks the tier that fits its shape — not the tier that flatters its historic score.</li><li><strong>Kill-rate formula drift</strong>. Stryker&#39;s HTML report exposes multiple numbers: <code>total MSI</code>, <code>covered MSI</code>, <code>killed / mutations</code>, <code>killed / (killed + survived)</code>. The SSOT pins the kill rate at <strong><code>killed / (killed + survived + timeout + error)</code></strong> so a package with a lot of <code>no-coverage</code> mutants is not penalised for lines the test suite never touches, and a package with <code>timeout</code> / <code>error</code> mutants is not silently rewarded.</li><li><strong>Regression detection drift</strong>. Rebuilding the baseline on every run misses regressions entirely. Comparing today&#39;s kill rate against a hard-coded number misses improvements. The SSOT pins baseline persistence at <code>.mutation-baseline/{package}.json</code>, tracked in git, so a mutation regression on a future PR shows up as a <strong>diff on the baseline JSON alongside the code diff</strong>.</li></ul><p>The 4 rules in <code>docs/concepts/mutation-testing-ssot.md</code> — kill-rate formula / 4-tier floor / baseline persistence / tier-aware 12-axis gate — are the smallest set that make kiwa mutation suites comparable across packages, milestones, and forks.</p><h2 id="_17-milestone-streak" tabindex="-1">17-milestone streak <a class="header-anchor" href="#_17-milestone-streak" aria-label="Permalink to &quot;17-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework depth) → v1.20 (Streaming depth) → v1.21 (Auth depth) → v1.22 (Auth depth II) → v1.23 (Payment depth) → v1.24 (Edge / Serverless depth) → v1.25 (Perf-harness sweep) → v1.26 (Database depth) → <strong>v1.27 (Mutation testing sweep)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100 % milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth II (SurrealDB / EdgeDB / Turso / CockroachDB / TimescaleDB / QuestDB)</li><li>Perf-harness sweep II — real-machine baseline (macOS ARM64 + Linux x86_64 + Windows x86_64 3 hardware matrix + CI reproducibility harness)</li><li>Mutation sweep II — property-based mutation (Stryker + fast-check integration + shrink parser)</li></ul><p>Feedback welcome on which of these should land next.</p>',15)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
